(() => {
  const atlas=document.getElementById('talisman-atlas'); if(!atlas)return;
  const sheet=document.createElement('link');sheet.rel='stylesheet';sheet.href='./talisman-catalog.css';document.head.append(sheet);
  const sources={peace:{name:'国史馆台湾文献馆 · 平安符',url:'https://dict.th.gov.tw/detailPage.aspx?ID=904',image:'https://dict.th.gov.tw/images/contentImages/0904.jpg'},house:{name:'国史馆台湾文献馆 · 镇宅版画',url:'https://dict.th.gov.tw/detailPage.aspx?ID=1707',image:'https://dict.th.gov.tw/images/contentImages/1707.jpg'},amulet:{name:'国史馆台湾文献馆 · 护符',url:'https://dict.th.gov.tw/detailPage.aspx?ID=1663',image:'https://dict.th.gov.tw/images/contentImages/1663-1.jpg'},wealth:{name:'朱越利 · 道教隐身神举例（中国道教学院）',url:'https://www.daoist.org/BookSearch%28test%29/list012/63-2-13.pdf'},temple:{name:'嗣汉张天师府 · 日常神符服务资料',url:'https://www.cts65.org/upload/20140730180146.pdf'},classic:{name:'《古今图书集成》艺术典第678卷 · 论符镇',url:'https://zh.wikisource.org/zh-hant/欽定古今圖書集成/博物彙編/藝術典/第678卷'}};
  const items=[
    {name:'财神符与招财镇宝',cat:'求财利市',word:'财',motif:'元宝 · 钱纹 · 财源祈愿',source:'wealth',use:'传统求财信仰中的祈愿类型，表达经营顺遂、财用充足与守财的愿望。',context:'所列研究讨论《太上正一盟威法箓》中的招财镇宝内容，说明道教求财传统存在文献脉络。',look:'“财神符”不是全国统一的一张图。需区分法箓、具体符式与现代祈愿图；本卡图形是主题示意，不是原典符文。',scope:'文献支持求财信仰与法箓主题；本条未取得可复刻的原典符式图版。'},
    {name:'赵公明镇宅符',cat:'求财利市',tags:['安家镇宅'],word:'赵',motif:'玄坛元帅 · 黑虎 · 镇宅版画',source:'house',use:'在民间镇宅版画中寄托家宅平安的愿望；赵公明同时具有武财神的信仰身份。',context:'文献馆记录的类型以骑黑虎的赵公明形象为辨识点。财神身份与某一张符的具体用途应分开说明。',look:'观察神像、坐骑、题字与印记。下方为镇宅版画条目的整幅参考图，不把其中未辨认的单幅直接指认为赵公明。'},
    {name:'镇宅平安符',cat:'安家镇宅',word:'宅',motif:'镇宅字样 · 长条符面 · 红印',source:'peace',use:'传统上祈求家宅安宁、合家平安，是平安符在住宅场景中的一种类型。',context:'文献馆记载，平安符可随身携带，也有用于门楣、神桌等家宅空间的类型。具体形式随宫庙、地区与传统而异。',look:'可观察题字中表达的家宅祈愿、符面分区与红色印记；不要据此认定所有镇宅符都必须使用同一版式。'},
    {name:'天师镇宅符',cat:'安家镇宅',word:'师',motif:'天师骑虎 · 神像与符文',source:'house',use:'传统镇宅版画中的祈安类型，寄托安宅、护家的愿望。',context:'文献馆介绍其常见于祈福法会或建醮等民俗场合，并记录了信众将版画带回家张挂的习俗。',look:'关注天师与虎的形象，以及文字区、印记区和神像区的布局。参考图是馆方条目的类型图版，非本站鉴定的单件法物。'},
    {name:'姜太公镇宅符',cat:'安家镇宅',word:'姜',motif:'姜太公形象 · 镇宅光明',source:'house',use:'借姜太公封神叙事表达镇宅光明、家宅安宁的愿望。',context:'此类图像属于道教与民间信仰交织的镇宅版画传统，不能将所有地区的民俗图像都归为同一法派。',look:'同时辨认人物题名与祝愿文字；仅凭人物轮廓不宜断定身份。'},
    {name:'剑狮符',cat:'安家镇宅',word:'狮',motif:'狮首 · 衔剑 · 彩印',source:'house',use:'传统上表达守护门户、镇宅的愿望。',context:'文献馆将其列为镇宅版画类型，图形与剑狮兽牌有联系，但纸上版画和建筑上的兽牌是不同载体。',look:'主要观察衔剑狮首、彩印色块及边框，区别神像型与兽首型版画。'},
    {name:'护身平安符',cat:'护身出行',word:'安',motif:'祈安文字 · 符面 · 神明印',source:'amulet',use:'传统上供个人寄托平安、护身的愿望，也常与香火袋相联系。',context:'文献馆记载了手书、符印印制、加盖宫庙神印及折叠携带等形式。',look:'先分清符纸、外袋和印记三个对象；外袋上的神像或祝词不一定就是里面符纸的图案。'},
    {name:'出行平安祈愿',cat:'护身出行',word:'行',motif:'平安 · 随身 · 旅途祈愿',source:'peace',use:'将一般平安信仰放到旅行、通勤等场景，表达一路平安的愿望。',context:'本条是按使用场景组织的学习主题，不宣称存在一幅跨流派统一的“出行符”。',look:'这里的图版是平安符资料，用于理解一般护身祈安形制，不作为特定交通或旅行符式的证据。'},
    {name:'文昌符',cat:'学业文昌',word:'文',motif:'文昌主题 · 读书与进学',source:'temple',use:'宫庙祈愿服务中与学业、读书及考试相关的类别。',context:'来源机构的日常神符资料列有文昌符。各地可能有不同图式、神名和题字，不能据名称推定统一笔画。',look:'本卡为文字与书卷主题示意；未采用无来源的网络符文。实际图版应记录其宫庙、年代和版本。',scope:'已核对资料列有名称；具体图式和仪式细节未作统一归纳。'},
    {name:'健康祈安符',cat:'健康祝愿',word:'康',motif:'康宁 · 平安 · 健康祝愿',source:'temple',use:'表达健康、康宁与照护亲人的愿望。',context:'来源机构的日常神符资料列有健康符。本条介绍宗教文化中的祝愿类别。',look:'“健康”是祈愿主题，不等于某一种固定符式；本站提供主题示意，未声称是治疗符的复原。',scope:'不具有医学治疗依据；不提供符灰、符水服用方法。'},
    {name:'祈福纳祥',cat:'祈福纳祥',word:'福',motif:'纳福字样 · 合家平安 · 吉祥祝词',source:'peace',use:'表达迎福、纳祥与家庭和乐的愿望。',context:'文献馆的平安符条目记录了多种祈安、纳福文字。这里按祝词和文化含义整理，而非规定一个统一的“纳福符”。',look:'比较“合家平安”“元亨利贞”等题字表达的范围；祝词、神名与符文应分别辨识。'},
    {name:'钟馗镇宅符',cat:'辟邪民俗',word:'馗',motif:'钟馗人物 · 节令镇宅版画',source:'house',use:'传统上用于镇宅除祟的民俗祈愿，常与端午或岁末的张贴习俗联系。',context:'文献馆将钟馗形象列入镇宅版画类型。人物画、年画、门画和符令之间存在交集，仍应保留各自的作品名称。',look:'观察人物题名、面貌、服饰与版画文字。整幅类型参考图不等于每一幅钟馗图都属于同一种符令。'},
    {name:'五岳镇宅符（文献条目）',cat:'安家镇宅',word:'岳',motif:'五岳名目 · 方位与安宅',source:'classic',use:'古籍中以五岳名目表达安宅与护守的传统愿望。',context:'《古今图书集成》艺术典第678卷收录《阳宅十书》论符镇内容，列有五岳镇宅符等条目。',look:'电子文字页包含图像缺失或未识读的位置，不能凭标题自行补画。此卡为五岳主题示意，不是北岳、东岳等原符的复刻。',scope:'保留历史记载性质；古籍中的效验宣称不是已验证效果。'}
  ];
  sources.tianguan={name:'国史馆台湾文献馆 · 天官财神',url:'https://dict.th.gov.tw/detailPage.aspx?ID=2489',image:'https://dict.th.gov.tw/images/contentImages/2489.jpg'};
  sources.sanguan={name:'国史馆台湾文献馆 · 三官大帝',url:'https://dict.th.gov.tw/detailPage.aspx?ID=1256',image:'https://dict.th.gov.tw/images/contentImages/1256.jpg'};
  items.push(
    {name:'天官赐福',cat:'三官祈愿',tags:['祈福纳祥','求财利市'],word:'福',motif:'天官神像 · 赐福题字 · 年画门贴',source:'tianguan',use:'传统上表达迎福纳吉、阖家顺遂的愿望；部分民俗年画也把天官视为赐福的财神。',context:'天官是三官之一，与上元节（农历正月十五）相联系。“天官赐福”既是祈愿文字，也可成为年画、神像和建筑装饰的主题。',look:'先读作品题名，再分辨神像、题字、吉祥纹样和符文。带“天官赐福”四字的门贴不一定是符令；主题相同也不代表图式相同。',scope:'本条展示馆方“天官财神”参考图与本站主题示意；并非一张全国通用的天官赐福符。'},
    {name:'地官赦罪',cat:'三官祈愿',tags:['祈福纳祥'],word:'赦',motif:'地官信仰 · 忏悔改过 · 三官图像',source:'sanguan',use:'传统信仰中表达祈求赦过、反省改过的愿望。',context:'地官与天官、水官同属三官信仰，通常联系中元节（农历七月十五）。',look:'馆方参考图为三官整体图像，不是单独地官符的鉴定图。具体人物位置、服色应结合该幅作品的题名与说明阅读。',scope:'“赦罪”是宗教文化用语，不表示免除现实中的法律责任。'},
    {name:'水官解厄',cat:'三官祈愿',tags:['祈福纳祥','护身出行'],word:'厄',motif:'水官信仰 · 解厄祈愿 · 三官图像',source:'sanguan',use:'传统信仰中表达消灾解厄、平安顺遂的愿望。',context:'水官与下元节（农历十月十五）相联系，与天官赐福、地官赦罪共同构成三官祈愿主题。',look:'馆方参考图介绍三官大帝形象，不是某一传承的水官符式复原。区分神像画、祈愿文字与有具体出处的符令。',scope:'解厄属于信仰表达，不构成对事故、疾病或灾害的预防保证。'}
  );
  const categories=['全部','三官祈愿','求财利市','安家镇宅','护身出行','学业文昌','健康祝愿','祈福纳祥','辟邪民俗'];
  function illustration(d){const forms={财:'<path d="M62 230 Q140 275 218 230 L195 280 H85 Z"/><ellipse cx="140" cy="238" rx="43" ry="22"/><circle cx="140" cy="158" r="39"/><path d="M128 146 H152 V170 H128 Z"/>',文:'<path d="M65 155 Q100 140 140 160 Q180 140 215 155 V280 Q180 265 140 285 Q100 265 65 280 Z M140 160 V285 M82 185 H120 M82 210 H120 M160 185 H198 M160 210 H198"/>',宅:'<path d="M60 210 L140 135 L220 210 M80 198 V285 H200 V198 M120 285 V230 H160 V285"/>',岳:'<path d="M50 285 L100 190 L135 250 L175 165 L230 285 Z M65 200 L90 155 L110 185"/>',行:'<path d="M65 285 Q85 220 140 240 T215 170 M160 170 H215 V225"/>',福:'<path d="M75 165 H205 V285 H75 Z M95 190 H185 V260 H95 Z M140 190 V260 M95 225 H185"/>'};return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 280 370" role="img" aria-label="${d.name}主题示意，非历史符式"><rect width="280" height="370" fill="#dcc28c"/><rect x="17" y="17" width="246" height="336" fill="none" stroke="#883b2e"/><text x="140" y="83" text-anchor="middle" fill="#883b2e" font-size="38" font-family="serif">${d.word}</text><g fill="none" stroke="#883b2e" stroke-width="4" stroke-linejoin="round">${forms[d.word]||'<circle cx="140" cy="218" r="60"/><path d="M140 155 V280 M80 218 H200 M98 176 L182 260 M98 260 L182 176"/>'}</g><text x="140" y="330" text-anchor="middle" fill="#883b2e" font-size="12">祈愿主题示意 · 非原典符式</text></svg>`;}
  const section=document.createElement('div');section.className='purpose-catalog';section.innerHTML=`<div class="platform-title"><p class="eyebrow">中国道教与民间信仰 · 按用途浏览</p><h2>符箓用途图鉴</h2><p>求财、安家、护身、学业、健康与纳福：了解传统祈愿、图像特征及流传背景。不同地区与传承各有图式，名称相同也可能画法不同。</p></div><div class="purpose-toolbar"><div class="purpose-filters" aria-label="符箓用途分类">${categories.map((c,i)=>`<button data-purpose-filter="${c}" class="${i?'':'active'}" aria-pressed="${!i}">${c}</button>`).join('')}</div><label><span class="sr-only">搜索符箓用途</span><input type="search" id="purpose-search" placeholder="搜索名称、用途、图案…"></label></div><p class="catalog-count" id="purpose-count" role="status"></p><div class="purpose-grid" id="purpose-grid"></div><div class="purpose-note"><b>读图说明</b><p>“传统作用”指信仰中的祈愿与民俗用途，不是可保证的效果。主题示意以图内文字标注；馆方图版在详情中展示并链接原页，图文权利归原来源，不提供馆方图版的再分发下载。</p></div>`;
  atlas.prepend(section);
  const oldTitle=atlas.querySelectorAll('.platform-title')[1];if(oldTitle)oldTitle.querySelector('h2').textContent='基础课：符箓结构与读图';
  const modal=document.createElement('dialog');modal.className='atlas-dialog purpose-dialog';document.body.append(modal);
  let filter='全部';const savedKey='xuandao-talisman-favorites-v1';let favorites=[];try{favorites=JSON.parse(localStorage.getItem(savedKey)||'[]');if(!Array.isArray(favorites))favorites=[];}catch{}
  function render(){const query=document.getElementById('purpose-search').value.trim().toLowerCase();const list=items.map((d,i)=>({d,i})).filter(({d})=>(filter==='全部'||d.cat===filter||d.tags?.includes(filter))&&[d.name,d.cat,d.motif,d.use].join(' ').toLowerCase().includes(query));document.getElementById('purpose-count').textContent=`当前 ${list.length} 项 / 共 ${items.length} 项 · 点击查看图案、用途与出处`;document.getElementById('purpose-grid').innerHTML=list.length?list.map(({d,i})=>`<button class="purpose-card" data-purpose-item="${i}">${illustration(d)}<div><small>${d.cat}${favorites.includes(i)?' · 已收藏':''}</small><h3>${d.name}</h3><p>${d.use}</p><span>${d.motif}</span><b>图案与传统用途 ↗</b></div></button>`).join(''):'<p class="purpose-empty">没有匹配项，请尝试“平安”“镇宅”或清空关键词。</p>';}
  section.querySelectorAll('[data-purpose-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.purposeFilter;section.querySelectorAll('[data-purpose-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b));});render();});document.getElementById('purpose-search').oninput=render;
  section.addEventListener('click',e=>{const btn=e.target.closest('[data-purpose-item]');if(!btn)return;const i=Number(btn.dataset.purposeItem),d=items[i],s=sources[d.source];modal.innerHTML=`<form method="dialog"><button class="dialog-close" aria-label="关闭">×</button></form><div class="atlas-detail"><div>${illustration(d)}<p class="source-caption">上图：本站原创祈愿主题示意，非传承符式。</p>${s.image?`<figure class="source-figure"><a href="${s.url}" target="_blank" rel="noopener"><img src="${s.image}" alt="${s.name}条目参考图版，具体图式请对照原页说明" loading="lazy" referrerpolicy="no-referrer"></a><figcaption>资料图版：${s.name}。这是条目参考图，包含的图式以馆方说明为准。<a href="${s.url}" target="_blank" rel="noopener">查看原页 ↗</a></figcaption></figure>`:''}</div><div><p class="eyebrow">${d.cat} · 用途资料卡</p><h2>${d.name}</h2><h3>传统作用与祈愿</h3><p>${d.use}</p><h3>文化背景</h3><p>${d.context}</p><h3>图案怎么看</h3><p>${d.look}</p>${d.scope?`<p class="purpose-scope">资料范围：${d.scope}</p>`:''}<h3>出处与核验</h3><a class="purpose-source" href="${s.url}" target="_blank" rel="noopener">${s.name} ↗</a><p class="source-caption">说明依据以上资料整理；本站主题示意与来源图版分开标识。</p><button class="button ink" id="purpose-save">${favorites.includes(i)?'取消本机收藏':'收藏到本机'}</button><p id="purpose-save-status" role="status"></p></div></div>`;modal.querySelector('#purpose-save').onclick=()=>{favorites=favorites.includes(i)?favorites.filter(n=>n!==i):[...favorites,i];try{localStorage.setItem(savedKey,JSON.stringify(favorites));modal.querySelector('#purpose-save').textContent=favorites.includes(i)?'取消本机收藏':'收藏到本机';modal.querySelector('#purpose-save-status').textContent=favorites.includes(i)?'已收藏，下次访问仍可看到收藏标记。':'已取消收藏。';render();}catch{modal.querySelector('#purpose-save-status').textContent='本机存储不可用。';}};modal.showModal();});render();
})();
